# ✅ best: O(n) time, O(1) space
def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b        # tuple swap — no temp variable
    return a

# ✅ generator — infinite, lazy, O(1) space
def fib_gen():
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b

